using FinTrack.Shared.Kernel.Ids;

namespace FinTrack.Budget.Domain.Journal;

/// <summary>
/// Identifies a journal entry. Generated by the client (a version 7 UUID, checked with
/// <see cref="StronglyTypedId.FromClient{TId}"/>), so a repeated command is recognised (invariant 13).
/// </summary>
public readonly record struct JournalEntryId : IStronglyTypedId<JournalEntryId>
{
    private JournalEntryId(Guid value) => Value = value;

    /// <inheritdoc />
    public Guid Value { get; }

    /// <inheritdoc />
    public static JournalEntryId From(Guid value) =>
        value == Guid.Empty ? throw new ArgumentException("A journal entry identifier cannot be empty.", nameof(value)) : new JournalEntryId(value);

    /// <summary>The identifier in the standard <c>D</c> format.</summary>
    public override string ToString() => Value.ToString();
}
